<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserAcceptedTermnsOfUse\Domain\ValueObject\Accessor\UserAcceptedTermnsOfUseAcceptDateAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserAcceptedTermnsOfUseAcceptDateAccessor trait.
 *
 * Covers null default, string/VO assignment via withAcceptDate,
 * getAcceptDate/acceptDate accessors, and isAcceptDateChanged with/without original.
 */
class UserAcceptedTermnsOfUseAcceptDateAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAcceptDate creates a new instance with the AcceptDate set
     * from a string value, and getAcceptDate returns the primitive string.
     */
    public function testWithAcceptDateFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserAcceptedTermnsOfUseAcceptDateAccessorUnitTest();

        // Act
        $result = $holder->withAcceptDate((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getAcceptDate());
    }
    /**
     * Asserts that withacceptDate has access to the value object
     * from a string value, and getAcceptDate returns the primitive string.
     */
    public function testWithAcceptDateFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserAcceptedTermnsOfUseAcceptDateAccessorUnitTest();

        // Act
        $result = $holder->withAcceptDate((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->acceptDate()->value());
    }
    public function testChangedAcceptDate(): void
    {
        // Arrange
        $holder = new ImplWithUserAcceptedTermnsOfUseAcceptDateAccessorUnitTest();
        $original = $holder->withAcceptDate( (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withAcceptDate( (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withAcceptDate((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isAcceptDateChanged();
        $withSame = $original->isAcceptDateChanged( $same );
        $withDiferent = $original->isAcceptDateChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserAcceptedTermnsOfUseAcceptDateAccessorUnitTest
{
  use UserAcceptedTermnsOfUseAcceptDateAccessor;
}
